import fs from 'node:fs';
import fsp from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import tls from 'node:tls';
import { getDomain } from 'tldts';
import { getTrustedCAs } from './tls-trust';

const COOKIE_FILE_HEADER =
  '# Netscape HTTP Cookie File\n# Generated by MDM for this yt-dlp run only.\n\n';

function normalizeHostname(hostname: string): string {
  return hostname.trim().toLowerCase().replace(/^\[|\]$/g, '').replace(/\.$/, '');
}

function isIpAddress(host: string): boolean {
  return /^\d{1,3}(?:\.\d{1,3}){3}$/.test(host) || host.includes(':');
}

export interface CookieDomain {
  domain: string;
  includeSubdomains: boolean;
}

/**
 * Chooses the narrowest cookie domain that still covers the page the user
 * opened. For `www.example.com` that is `.example.com`; for a tenant on a
 * shared host such as `foo.github.io` it stays `.foo.github.io`.
 */
export function cookieDomainFor(hostname: string): CookieDomain | null {
  const host = normalizeHostname(hostname);
  if (!host) return null;
  if (host === 'localhost' || isIpAddress(host) || !host.includes('.')) {
    return { domain: host, includeSubdomains: false };
  }
  // Uses the real Public Suffix List (including private suffixes such as
  // github.io or myshopify.com). A hand-written list misses whole countries:
  // without "com.eg" a cookie for shop.example.com.eg covered every .com.eg site.
  const domain = getDomain(host, { allowPrivateDomains: true });
  // null: the host is itself a public suffix, so no cookie may be issued for it.
  if (!domain) return null;
  return { domain, includeSubdomains: true };
}

function parseCookieHeader(header: string): Array<{ name: string; value: string }> {
  const seen = new Set<string>();
  const pairs: Array<{ name: string; value: string }> = [];
  for (const part of header.split(';')) {
    const equals = part.indexOf('=');
    if (equals <= 0) continue;
    const name = part.slice(0, equals).trim();
    const value = part.slice(equals + 1).trim();
    // The Netscape format is tab separated and has no escaping. Drop anything
    // that could break the file or inject a second cookie record.
    if (
      !/^[!#$%&'*+\-.^_`|~0-9A-Za-z]+$/.test(name) ||
      name.startsWith('$') ||
      /[\t\r\n\0]/.test(value)
    ) {
      continue;
    }
    if (seen.has(name)) continue;
    seen.add(name);
    pairs.push({ name, value });
  }
  return pairs;
}

export function cookieHeaderValue(headers: Record<string, string>, cookies: string): string {
  const supplied = cookies.trim();
  if (supplied) return supplied;
  const entry = Object.entries(headers).find(([key]) => key.toLowerCase() === 'cookie');
  return entry?.[1]?.trim() ?? '';
}

/**
 * Builds a cookie file scoped to the page's own site instead of passing one
 * global `Cookie:` header to every host yt-dlp contacts. Third-party media
 * hosts therefore never receive the browser session.
 */
export function buildYtDlpCookieFile(url: string, cookieHeader: string): string | null {
  const pairs = parseCookieHeader(cookieHeader);
  if (pairs.length === 0) return null;
  let parsed: URL;
  try {
    parsed = new URL(url);
  } catch {
    return null;
  }
  if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') return null;
  const scope = cookieDomainFor(parsed.hostname);
  if (!scope) return null;
  const domain = scope.includeSubdomains ? `.${scope.domain}` : scope.domain;
  const includeSubdomains = scope.includeSubdomains ? 'TRUE' : 'FALSE';
  // Mark the cookies secure when the page itself is HTTPS; a downgraded
  // request then cannot replay them.
  const secure = parsed.protocol === 'https:' ? 'TRUE' : 'FALSE';
  const lines = pairs.map(
    ({ name, value }) => `${domain}\t${includeSubdomains}\t/\t${secure}\t0\t${name}\t${value}`
  );
  return `${COOKIE_FILE_HEADER}${lines.join('\n')}\n`;
}

let caBundlePromise: Promise<string | null> | null = null;

function trustBundle(): string[] {
  const merged = getTrustedCAs();
  if (merged && merged.length > 0) return merged;
  // No system store available: still hand yt-dlp the Mozilla roots (what
  // certifi provides) so switching off certifi never narrows what it trusts.
  const get = (tls as unknown as { getCACertificates?: (type: string) => string[] }).getCACertificates;
  try {
    const defaults = get?.call(tls, 'default');
    if (defaults && defaults.length > 0) return defaults;
  } catch {
    // Fall through to the bundled roots.
  }
  return [...tls.rootCertificates];
}

async function writeCaBundle(): Promise<string | null> {
  const directory = await fsp.mkdtemp(path.join(os.tmpdir(), 'mdm-ca-'));
  const file = path.join(directory, 'ca-bundle.pem');
  await fsp.writeFile(file, `${trustBundle().join('\n')}\n`, { mode: 0o600 });
  process.once('exit', () => {
    try {
      fs.rmSync(directory, { recursive: true, force: true });
    } catch {
      // Best effort; the temp directory is cleaned by the OS.
    }
  });
  return file;
}

/**
 * yt-dlp trusts only its bundled certifi list by default, so a root installed
 * by antivirus or a corporate proxy is rejected. `--compat-options no-certifi`
 * makes it use the OpenSSL/OS store instead, and SSL_CERT_FILE points that
 * store at the same merged list the HTTP engine uses. (`--ca-bundle` is not a
 * yt-dlp option, and SSL_CERT_FILE alone is ignored while certifi is active.)
 */
export function getYtDlpCaBundle(): Promise<string | null> {
  if (!caBundlePromise) caBundlePromise = writeCaBundle().catch(() => null);
  return caBundlePromise;
}

export interface YtDlpRequestArgs {
  args: string[];
  /** Extra environment variables for the yt-dlp process. */
  env: Record<string, string>;
  cleanup: () => Promise<void>;
}

/**
 * Creates the per-run cookie (and CA) files and returns the matching yt-dlp
 * arguments. Callers must always run `cleanup`, including on timeout/cancel.
 */
export async function prepareYtDlpRequest(
  url: string,
  headers: Record<string, string>,
  cookies: string
): Promise<YtDlpRequestArgs> {
  const args: string[] = [];
  const env: Record<string, string> = {};
  const cleanups: Array<() => Promise<void>> = [];

  try {
    const cookieHeader = cookieHeaderValue(headers, cookies);
    const cookieFile = buildYtDlpCookieFile(url, cookieHeader);
    if (cookieFile) {
      const directory = await fsp.mkdtemp(path.join(os.tmpdir(), 'mdm-cookies-'));
      cleanups.push(() => fsp.rm(directory, { recursive: true, force: true }));
      const file = path.join(directory, 'cookies.txt');
      await fsp.writeFile(file, cookieFile, { mode: 0o600 });
      args.push('--cookies', file);
    }

    const userAgent = headerValue(headers, 'user-agent');
    if (userAgent) args.push('--user-agent', userAgent);
    const language = headerValue(headers, 'accept-language');
    if (language) args.push('--add-header', `Accept-Language: ${language}`);
    const referrer = headerValue(headers, 'referer');
    if (referrer) args.push('--add-header', `Referer: ${referrer}`);

    const caBundle = await getYtDlpCaBundle();
    if (caBundle) {
      args.push('--compat-options', 'no-certifi');
      env.SSL_CERT_FILE = caBundle;
    }
  } catch (error) {
    for (const cleanup of cleanups) await cleanup().catch(() => undefined);
    throw error;
  }

  return {
    args,
    env,
    cleanup: async () => {
      for (const cleanup of cleanups) await cleanup().catch(() => undefined);
    }
  };
}

function headerValue(headers: Record<string, string>, name: string): string {
  const entry = Object.entries(headers).find(([key]) => key.toLowerCase() === name);
  return entry?.[1]?.trim() ?? '';
}
